   202→// NewClient creates a new SSH/SFTP client.
   203→func NewClient(config Config) (*Client, error) {
   204→	authMethods, err := buildAuthMethods(config)
   205→	if err != nil {
   206→		return nil, err
   207→	}
   208→
   209→	if len(authMethods) == 0 {
   210→		return nil, fmt.Errorf("no SSH authentication method configured")
   211→	}
   212→
   213→	timeout := config.Timeout
   214→	if timeout == 0 {
   215→		timeout = 30 * time.Second
   216→	}
   217→
   218→	hostKeyCallback, err := buildHostKeyCallback(config)
   219→	if err != nil {
   220→		return nil, fmt.Errorf("failed to configure host key verification: %w", err)
   221→	}
   222→
   223→	port := config.Port
   224→	if port == 0 {
   225→		port = 22
   226→	}
   227→
   228→	sshConfig := &ssh.ClientConfig{
   229→		User:            config.User,
   230→		Auth:            authMethods,
   231→		HostKeyCallback: hostKeyCallback,
   232→		Timeout:         timeout,
   233→	}
   234→
   235→	var sshClient *ssh.Client
   236→	var bastionClient *ssh.Client
   237→
   238→	targetAddr := fmt.Sprintf("%s:%d", config.Host, port)
   239→
   240→	if config.BastionHost != "" {
   241→		bastionClient, err = connectToBastion(config, timeout)
   242→		if err != nil {
   243→			return nil, fmt.Errorf("failed to connect to bastion host: %w", err)
   244→		}
   245→
   246→		conn, err := bastionClient.Dial("tcp", targetAddr)
   247→		if err != nil {
   248→			bastionClient.Close()
   249→			return nil, fmt.Errorf("failed to dial target through bastion: %w", err)
   250→		}
   251→
   252→		ncc, chans, reqs, err := ssh.NewClientConn(conn, targetAddr, sshConfig)
   253→		if err != nil {
   254→			conn.Close()
   255→			bastionClient.Close()
   256→			return nil, fmt.Errorf("failed to create SSH connection through bastion: %w", err)
   257→		}
   258→
   259→		sshClient = ssh.NewClient(ncc, chans, reqs)
   260→	} else {
   261→		sshClient, err = ssh.Dial("tcp", targetAddr, sshConfig)
   262→		if err != nil {
   263→			return nil, fmt.Errorf("failed to connect to %s: %w", targetAddr, err)
   264→		}
   265→	}
   266→
   267→	rawSftpClient, err := sftp.NewClient(sshClient)
   268→	if err != nil {
   269→		sshClient.Close()
   270→		if bastionClient != nil {
   271→			bastionClient.Close()
   272→		}
   273→		return nil, fmt.Errorf("failed to create SFTP client: %w", err)
   274→	}
   275→
   276→	return &Client{
   277→		sshClient:     &SSHClientWrapper{client: sshClient},
   278→		sftpClient:    &SFTPClientWrapper{client: rawSftpClient},
   279→		bastionClient: bastionClient,
   280→	}, nil
   281→}
