   283→func connectToBastion(config Config, timeout time.Duration) (*ssh.Client, error) {
   284→	var authMethods []ssh.AuthMethod
   285→
   286→	if config.BastionPassword != "" {
   287→		authMethods = append(authMethods, ssh.Password(config.BastionPassword))
   288→	} else {
   289→		var keyData []byte
   290→		var err error
   291→
   292→		if config.BastionKey != "" {
   293→			keyData = []byte(config.BastionKey)
   294→		} else if config.BastionKeyPath != "" {
   295→			keyData, err = os.ReadFile(ExpandPath(config.BastionKeyPath))
   296→			if err != nil {
   297→				return nil, fmt.Errorf("failed to read bastion key file: %w", err)
   298→			}
   299→		} else {
   300→			if config.PrivateKey != "" {
   301→				keyData = []byte(config.PrivateKey)
   302→			} else if config.KeyPath != "" {
   303→				keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   304→				if err != nil {
   305→					return nil, fmt.Errorf("failed to read key file for bastion: %w", err)
   306→				}
   307→			} else {
   308→				return nil, fmt.Errorf("no SSH key configured for bastion host")
   309→			}
   310→		}
   311→
   312→		signer, err := ssh.ParsePrivateKey(keyData)
   313→		if err != nil {
   314→			return nil, fmt.Errorf("failed to parse bastion SSH key: %w", err)
   315→		}
   316→		authMethods = append(authMethods, ssh.PublicKeys(signer))
   317→	}
   318→
   319→	bastionUser := config.BastionUser
   320→	if bastionUser == "" {
   321→		bastionUser = config.User
   322→	}
   323→
   324→	bastionPort := config.BastionPort
   325→	if bastionPort == 0 {
   326→		bastionPort = 22
   327→	}
   328→
   329→	hostKeyCallback, err := buildHostKeyCallback(config)
   330→	if err != nil {
   331→		return nil, fmt.Errorf("failed to configure host key verification for bastion: %w", err)
   332→	}
   333→
   334→	bastionConfig := &ssh.ClientConfig{
   335→		User:            bastionUser,
   336→		Auth:            authMethods,
   337→		HostKeyCallback: hostKeyCallback,
   338→		Timeout:         timeout,
   339→	}
   340→
   341→	bastionAddr := fmt.Sprintf("%s:%d", config.BastionHost, bastionPort)
   342→	return ssh.Dial("tcp", bastionAddr, bastionConfig)
   343→}
