   345→func buildHostKeyCallback(config Config) (ssh.HostKeyCallback, error) {
   346→	if config.InsecureIgnoreHostKey {
   347→		return ssh.InsecureIgnoreHostKey(), nil
   348→	}
   349→
   350→	if config.KnownHostsFile != "" {
   351→		expandedPath := ExpandPath(config.KnownHostsFile)
   352→		callback, err := knownhosts.New(expandedPath)
   353→		if err != nil {
   354→			return nil, fmt.Errorf("failed to load known_hosts file %s: %w", expandedPath, err)
   355→		}
   356→		return callback, nil
   357→	}
   358→
   359→	homeDir, err := os.UserHomeDir()
   360→	if err == nil {
   361→		defaultKnownHosts := filepath.Join(homeDir, ".ssh", "known_hosts")
   362→		if _, err := os.Stat(defaultKnownHosts); err == nil {
   363→			callback, err := knownhosts.New(defaultKnownHosts)
   364→			if err == nil {
   365→				return callback, nil
   366→			}
   367→		}
   368→	}
   369→
   370→	return func(hostname string, remote net.Addr, key ssh.PublicKey) error {
   371→		return nil
   372→	}, nil
   373→}
   374→
   375→// ExpandPath expands ~ to home directory.
   376→func ExpandPath(path string) string {
   377→	if strings.HasPrefix(path, "~/") {
   378→		homeDir, err := os.UserHomeDir()
   379→		if err == nil {
   380→			return filepath.Join(homeDir, path[2:])
   381→		}
   382→	}
   383→	return path
   384→}
