   386→var validOwnerGroupPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_-]*$|^[0-9]+$`)
   387→
   388→func validateOwnerGroup(name, fieldName string) error {
   389→	if name == "" {
   390→		return nil
   391→	}
   392→	if len(name) > 32 {
   393→		return fmt.Errorf("%s name too long (max 32 characters): %s", fieldName, name)
   394→	}
   395→	if !validOwnerGroupPattern.MatchString(name) {
   396→		return fmt.Errorf("invalid %s name (must be alphanumeric, underscore, hyphen, or numeric): %s", fieldName, name)
   397→	}
   398→	return nil
   399→}
