   401→// ShellQuote returns a shell-escaped version of the string.
   402→func ShellQuote(s string) string {
   403→	if s == "" {
   404→		return "''"
   405→	}
   406→	escaped := strings.ReplaceAll(s, "'", "'\"'\"'")
   407→	return "'" + escaped + "'"
   408→}
