   410→var validModePattern = regexp.MustCompile(`^[0-7]{3,4}$`)
   411→
   412→// ValidateMode checks if a file mode string is valid.
   413→func ValidateMode(mode string) error {
   414→	if mode == "" {
   415→		return nil
   416→	}
   417→	if !validModePattern.MatchString(mode) {
   418→		return fmt.Errorf("invalid mode %q: must be 3-4 octal digits (e.g., \"644\", \"0755\")", mode)
   419→	}
   420→	return nil
   421→}
