   423→func buildAuthMethods(config Config) ([]ssh.AuthMethod, error) {
   424→	var authMethods []ssh.AuthMethod
   425→
   426→	authMethod := config.AuthMethod
   427→	if authMethod == "" {
   428→		authMethod = inferAuthMethod(config)
   429→	}
   430→
   431→	switch authMethod {
   432→	case AuthMethodPassword:
   433→		if config.Password == "" {
   434→			return nil, fmt.Errorf("password authentication requires password to be set")
   435→		}
   436→		authMethods = append(authMethods, ssh.Password(config.Password))
   437→
   438→	case AuthMethodCertificate:
   439→		certAuth, err := buildCertificateAuth(config)
   440→		if err != nil {
   441→			return nil, fmt.Errorf("certificate authentication failed: %w", err)
   442→		}
   443→		authMethods = append(authMethods, certAuth)
   444→
   445→	case AuthMethodPrivateKey, "":
   446→		keyAuth, err := buildPrivateKeyAuth(config)
   447→		if err != nil {
   448→			return nil, err
   449→		}
   450→		authMethods = append(authMethods, keyAuth)
   451→	}
   452→
   453→	return authMethods, nil
   454→}
   455→
   456→func inferAuthMethod(config Config) AuthMethod {
   457→	if config.Password != "" {
   458→		return AuthMethodPassword
   459→	}
   460→	if config.Certificate != "" || config.CertificatePath != "" {
   461→		return AuthMethodCertificate
   462→	}
   463→	return AuthMethodPrivateKey
   464→}
   465→
   466→func buildPrivateKeyAuth(config Config) (ssh.AuthMethod, error) {
   467→	var keyData []byte
   468→	var err error
   469→
   470→	if config.PrivateKey != "" {
   471→		keyData = []byte(config.PrivateKey)
   472→	} else if config.KeyPath != "" {
   473→		keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   474→		if err != nil {
   475→			return nil, fmt.Errorf("failed to read SSH key file: %w", err)
   476→		}
   477→	} else {
   478→		return nil, fmt.Errorf("no SSH private key provided (set private_key or key_path)")
   479→	}
   480→
   481→	signer, err := ssh.ParsePrivateKey(keyData)
   482→	if err != nil {
   483→		return nil, fmt.Errorf("failed to parse SSH private key: %w", err)
   484→	}
   485→
   486→	return ssh.PublicKeys(signer), nil
   487→}
   488→
   489→func buildCertificateAuth(config Config) (ssh.AuthMethod, error) {
   490→	var keyData []byte
   491→	var err error
   492→
   493→	if config.PrivateKey != "" {
   494→		keyData = []byte(config.PrivateKey)
   495→	} else if config.KeyPath != "" {
   496→		keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   497→		if err != nil {
   498→			return nil, fmt.Errorf("failed to read private key file: %w", err)
   499→		}
   500→	} else {
   501→		return nil, fmt.Errorf("certificate auth requires private key (set private_key or key_path)")
   502→	}
   503→
   504→	signer, err := ssh.ParsePrivateKey(keyData)
   505→	if err != nil {
   506→		return nil, fmt.Errorf("failed to parse private key: %w", err)
   507→	}
   508→
   509→	var certData []byte
   510→	if config.Certificate != "" {
   511→		certData = []byte(config.Certificate)
   512→	} else if config.CertificatePath != "" {
   513→		certData, err = os.ReadFile(ExpandPath(config.CertificatePath))
   514→		if err != nil {
   515→			return nil, fmt.Errorf("failed to read certificate file: %w", err)
   516→		}
   517→	} else {
   518→		return nil, fmt.Errorf("certificate auth requires certificate (set certificate or certificate_path)")
   519→	}
   520→
   521→	pubKey, _, _, _, err := ssh.ParseAuthorizedKey(certData)
   522→	if err != nil {
   523→		return nil, fmt.Errorf("failed to parse certificate: %w", err)
   524→	}
   525→
   526→	cert, ok := pubKey.(*ssh.Certificate)
   527→	if !ok {
   528→		return nil, fmt.Errorf("provided file is not an SSH certificate")
   529→	}
   530→
   531→	certSigner, err := ssh.NewCertSigner(cert, signer)
   532→	if err != nil {
   533→		return nil, fmt.Errorf("failed to create certificate signer: %w", err)
   534→	}
   535→
   536→	return ssh.PublicKeys(certSigner), nil
   537→}
