   553→// UploadFile uploads a local file to the remote host.
   554→func (c *Client) UploadFile(localPath, remotePath string) error {
   555→	localFile, err := os.Open(localPath)
   556→	if err != nil {
   557→		return fmt.Errorf("failed to open local file: %w", err)
   558→	}
   559→	defer localFile.Close()
   560→
   561→	remoteDir := filepath.Dir(remotePath)
   562→	if remoteDir != "" && remoteDir != "/" && remoteDir != "." {
   563→		if err := c.sftpClient.MkdirAll(remoteDir); err != nil {
   564→			return fmt.Errorf("failed to create remote directory %s: %w", remoteDir, err)
   565→		}
   566→	}
   567→
   568→	remoteFile, err := c.sftpClient.Create(remotePath)
   569→	if err != nil {
   570→		return fmt.Errorf("failed to create remote file: %w", err)
   571→	}
   572→	defer remoteFile.Close()
   573→
   574→	_, err = io.Copy(remoteFile, localFile)
   575→	if err != nil {
   576→		return fmt.Errorf("failed to copy file content: %w", err)
   577→	}
   578→
   579→	return nil
   580→}
