   582→// UploadContent uploads content directly to the remote host.
   583→func (c *Client) UploadContent(content []byte, remotePath string) error {
   584→	remoteDir := filepath.Dir(remotePath)
   585→	if remoteDir != "" && remoteDir != "/" && remoteDir != "." {
   586→		if err := c.sftpClient.MkdirAll(remoteDir); err != nil {
   587→			return fmt.Errorf("failed to create remote directory %s: %w", remoteDir, err)
   588→		}
   589→	}
   590→
   591→	remoteFile, err := c.sftpClient.Create(remotePath)
   592→	if err != nil {
   593→		return fmt.Errorf("failed to create remote file: %w", err)
   594→	}
   595→	defer remoteFile.Close()
   596→
   597→	_, err = remoteFile.Write(content)
   598→	if err != nil {
   599→		return fmt.Errorf("failed to write file content: %w", err)
   600→	}
   601→
   602→	return nil
   603→}
