   605→// GetFileHash returns the SHA256 hash of a remote file.
   606→func (c *Client) GetFileHash(remotePath string) (string, error) {
   607→	file, err := c.sftpClient.Open(remotePath)
   608→	if err != nil {
   609→		return "", fmt.Errorf("failed to open remote file: %w", err)
   610→	}
   611→	defer file.Close()
   612→
   613→	h := sha256.New()
   614→	if _, err := io.Copy(h, file); err != nil {
   615→		return "", fmt.Errorf("failed to read remote file: %w", err)
   616→	}
   617→
   618→	return "sha256:" + hex.EncodeToString(h.Sum(nil)), nil
   619→}
