   621→// SetFileAttributes sets ownership and permissions on a remote file.
   622→func (c *Client) SetFileAttributes(remotePath, owner, group, mode string) error {
   623→	if err := validateOwnerGroup(owner, "owner"); err != nil {
   624→		return err
   625→	}
   626→	if err := validateOwnerGroup(group, "group"); err != nil {
   627→		return err
   628→	}
   629→	if err := ValidateMode(mode); err != nil {
   630→		return err
