	exists, err := client.FileExists(data.RemotePath.ValueString())
	if err != nil {
		resp.Diagnostics.AddError("Failed to check remote file", err.Error())
		return
	}

	if !exists {
		// File was deleted externally - remove from state.
		resp.State.RemoveResource(ctx)
		return
