package ssh

import (
	"bytes"
	"errors"
	"io"
	"os"
	"time"
)

// MockSFTPClient implements SFTPClientInterface for testing.
type MockSFTPClient struct {
	Files         map[string][]byte
	OpenError     error
	CreateError   error
	RemoveError   error
	StatError     error
	ChmodError    error
	MkdirAllError error
	CloseError    error
	ReadError     error
	WriteError    error
	Permissions   map[string]os.FileMode
}

var _ SFTPClientInterface = (*MockSFTPClient)(nil)

func NewMockSFTPClient() *MockSFTPClient {
	return &MockSFTPClient{
		Files:       make(map[string][]byte),
		Permissions: make(map[string]os.FileMode),
	}
}

func (m *MockSFTPClient) Open(path string) (SFTPFile, error) {
	if m.OpenError != nil {
		return nil, m.OpenError
	}
	content, exists := m.Files[path]
	if !exists {
		return nil, os.ErrNotExist
	}
	return &MockSFTPFile{Buffer: bytes.NewBuffer(content), ReadError: m.ReadError}, nil
}

func (m *MockSFTPClient) Create(path string) (SFTPFile, error) {
	if m.CreateError != nil {
		return nil, m.CreateError
	}
	file := &MockSFTPFile{
		Buffer:     &bytes.Buffer{},
		WriteError: m.WriteError,
		OnClose: func(data []byte) {
			m.Files[path] = data
		},
	}
	return file, nil
}

func (m *MockSFTPClient) Remove(path string) error {
	if m.RemoveError != nil {
		return m.RemoveError
	}
	if _, exists := m.Files[path]; !exists {
		return os.ErrNotExist
	}
	delete(m.Files, path)
	return nil
}

func (m *MockSFTPClient) Stat(path string) (os.FileInfo, error) {
	if m.StatError != nil {
		return nil, m.StatError
	}
	content, exists := m.Files[path]
	if !exists {
		return nil, os.ErrNotExist
	}
	mode := m.Permissions[path]
	if mode == 0 {
		mode = 0644
	}
	return &mockFileInfo{
		name: path,
		size: int64(len(content)),
		mode: mode,
	}, nil
}

func (m *MockSFTPClient) Chmod(path string, mode os.FileMode) error {
	if m.ChmodError != nil {
		return m.ChmodError
	}
	if _, exists := m.Files[path]; !exists {
		return os.ErrNotExist
	}
	m.Permissions[path] = mode
	return nil
}

func (m *MockSFTPClient) MkdirAll(path string) error {
	return m.MkdirAllError
}

func (m *MockSFTPClient) Close() error {
	return m.CloseError
}

// MockSFTPFile implements SFTPFile for testing.
type MockSFTPFile struct {
	Buffer     *bytes.Buffer
	CloseError error
	ReadError  error
	WriteError error
	OnClose    func([]byte)
}

var _ SFTPFile = (*MockSFTPFile)(nil)

func (f *MockSFTPFile) Read(p []byte) (int, error) {
	if f.ReadError != nil {
		return 0, f.ReadError
	}
	return f.Buffer.Read(p)
}

func (f *MockSFTPFile) Write(p []byte) (int, error) {
	if f.WriteError != nil {
		return 0, f.WriteError
	}
	return f.Buffer.Write(p)
}

func (f *MockSFTPFile) Close() error {
	if f.OnClose != nil {
		f.OnClose(f.Buffer.Bytes())
	}
	return f.CloseError
}

// mockFileInfo implements os.FileInfo for testing.
type mockFileInfo struct {
	name    string
	size    int64
	mode    os.FileMode
	modTime time.Time
	isDir   bool
}

func (m *mockFileInfo) Name() string       { return m.name }
func (m *mockFileInfo) Size() int64        { return m.size }
func (m *mockFileInfo) Mode() os.FileMode  { return m.mode }
func (m *mockFileInfo) ModTime() time.Time { return m.modTime }
func (m *mockFileInfo) IsDir() bool        { return m.isDir }
func (m *mockFileInfo) Sys() interface{}   { return nil }

// MockSSHSession represents a mock SSH session for testing.
type MockSSHSession struct {
	StdoutData string
	StderrData string
	RunError   error
	stdout     io.Writer
	stderr     io.Writer
}

func (s *MockSSHSession) Run(cmd string) error {
	if s.stdout != nil && s.StdoutData != "" {
		s.stdout.Write([]byte(s.StdoutData))
	}
	if s.stderr != nil && s.StderrData != "" {
		s.stderr.Write([]byte(s.StderrData))
	}
	return s.RunError
}

func (s *MockSSHSession) Close() error { return nil }

func (s *MockSSHSession) SetStdout(w io.Writer) { s.stdout = w }
func (s *MockSSHSession) SetStderr(w io.Writer) { s.stderr = w }

// MockSSHClient implements SSHClientInterface for testing.
type MockSSHClient struct {
	Session        *MockSSHSession
	NewSessionErr  error
	CloseError     error
}

var _ SSHClientInterface = (*MockSSHClient)(nil)

func NewMockSSHClientWithSession(session *MockSSHSession) *MockSSHClient {
	return &MockSSHClient{
		Session: session,
	}
}

func (m *MockSSHClient) NewSession() (SSHSession, error) {
	if m.NewSessionErr != nil {
		return nil, m.NewSessionErr
	}
	return m.Session, nil
}

func (m *MockSSHClient) Close() error {
	return m.CloseError
}

// Pre-defined errors for testing.
var (
	ErrMockConnection = errors.New("mock connection error")
	ErrMockOpen       = errors.New("mock open error")
	ErrMockCreate     = errors.New("mock create error")
	ErrMockRemove     = errors.New("mock remove error")
	ErrMockStat       = errors.New("mock stat error")
	ErrMockChmod      = errors.New("mock chmod error")
	ErrMockMkdirAll   = errors.New("mock mkdir all error")
	ErrMockCommand    = errors.New("mock command error")
	ErrMockSession    = errors.New("mock session error")
	ErrMockRead       = errors.New("mock read error")
	ErrMockWrite      = errors.New("mock write error")
)

