func TestClient_GetFileHash(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name        string
		fileContent []byte
		filePath    string
		wantErr     bool
	}{
		{
			name:        "hash text file",
			fileContent: []byte("version: '3.8'\nservices:\n  nginx:\n    image: nginx"),
			filePath:    "/opt/docker-compose.yaml",
			wantErr:     false,
		},
		{
			name:        "hash empty file",
			fileContent: []byte{},
			filePath:    "/opt/empty.yaml",
			wantErr:     false,
		},
		{
			name:        "file not found",
			fileContent: nil,
			filePath:    "/nonexistent/file",
			wantErr:     true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			mockSFTP := NewMockSFTPClient()
			if tt.fileContent != nil {
				mockSFTP.Files[tt.filePath] = tt.fileContent
			}

			client := &Client{
				sftpClient: mockSFTP,
			}

			hash, err := client.GetFileHash(tt.filePath)
			if (err != nil) != tt.wantErr {
				t.Errorf("GetFileHash() error = %v, wantErr %v", err, tt.wantErr)
				return
			}

			if !tt.wantErr {
				// Verify hash is correct
				h := sha256.New()
				h.Write(tt.fileContent)
				expected := "sha256:" + hex.EncodeToString(h.Sum(nil))
				if hash != expected {
					t.Errorf("GetFileHash() = %q, want %q", hash, expected)
				}
			}
		})
	}
}

