func TestClient_RunCommand(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name       string
		command    string
		stdoutData string
		stderrData string
		runError   error
		sessionErr error
		wantStdout string
		wantStderr string
		wantErr    bool
	}{
		{
			name:       "successful command",
			command:    "echo hello",
			stdoutData: "hello\n",
			stderrData: "",
			wantStdout: "hello\n",
			wantStderr: "",
			wantErr:    false,
		},
		{
			name:       "command with stderr",
			command:    "ls /nonexistent",
			stdoutData: "",
			stderrData: "No such file or directory\n",
			runError:   ErrMockCommand,
			wantStdout: "",
			wantStderr: "No such file or directory\n",
			wantErr:    true,
		},
		{
			name:       "command with both stdout and stderr",
			command:    "make",
			stdoutData: "Building...\n",
			stderrData: "warning: unused variable\n",
			wantStdout: "Building...\n",
			wantStderr: "warning: unused variable\n",
			wantErr:    false,
		},
		{
			name:       "session creation error",
			command:    "echo test",
			sessionErr: ErrMockSession,
			wantErr:    true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			session := &MockSSHSession{
				StdoutData: tt.stdoutData,
				StderrData: tt.stderrData,
				RunError:   tt.runError,
			}

			mockSSH := &MockSSHClient{
				Session:       session,
				NewSessionErr: tt.sessionErr,
			}

			client := &Client{
				sshClient: mockSSH,
			}

			stdout, stderr, err := client.RunCommand(tt.command)

			if (err != nil) != tt.wantErr {
				t.Errorf("RunCommand() error = %v, wantErr %v", err, tt.wantErr)
				return
			}

			if !tt.wantErr {
				if stdout != tt.wantStdout {
					t.Errorf("RunCommand() stdout = %q, want %q", stdout, tt.wantStdout)
				}
				if stderr != tt.wantStderr {
					t.Errorf("RunCommand() stderr = %q, want %q", stderr, tt.wantStderr)
				}
			}
		})
	}
}

