			name: "certificate auth without private key",
			config: Config{
				AuthMethod:  AuthMethodCertificate,
				Certificate: "cert-content",
			},
			wantErr: true,
			errMsg:  "certificate auth requires private key",
		},
		{
			name: "certificate auth without certificate",
			config: Config{
				AuthMethod: AuthMethodCertificate,
				PrivateKey: testKey,
			},
			wantErr: true,
			errMsg:  "certificate auth requires certificate",
