				AuthMethod:  AuthMethodCertificate,
				PrivateKey:  testKey,
				Certificate: validPubKeyNotCert,
			},
			wantErr: true,
			errMsg:  "not an SSH certificate",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			_, err := buildAuthMethods(tt.config)
			if (err != nil) != tt.wantErr {
				t.Errorf("buildAuthMethods() error = %v, wantErr %v", err, tt.wantErr)
			}
			if tt.wantErr && err != nil && tt.errMsg != "" {
				if !contains(err.Error(), tt.errMsg) {
					t.Errorf("buildAuthMethods() error = %v, want error containing %q", err, tt.errMsg)
				}
			}
		})
	}
}

