					"content_hash":            tftypes.NewValue(tftypes.String, tftypes.UnknownValue),
				})
			}

			plan := tfsdk.Plan{
				Schema: schemaResp.Schema,
				Raw:    planValue,
			}

			req := planmodifier.StringRequest{
				Plan: plan,
