	bastionConfig := &ssh.ClientConfig{
		User:            bastionUser,
		Auth:            authMethods,
		HostKeyCallback: hostKeyCallback,
		Timeout:         timeout,
	}

	bastionAddr := fmt.Sprintf("%s:%d", config.BastionHost, bastionPort)
	return ssh.Dial("tcp", bastionAddr, bastionConfig)
}

