   123→		{
   124→			name:    "empty content",
   125→			content: "",
   126→		},
   127→		{
   128→			name: "multiline content",
   129→			content: `version: '3.8'
   130→services:
   131→  nginx:
   132→    image: nginx:alpine
   133→    ports:
   134→      - "80:80"`,
   135→		},
   136→	}
   137→
   138→	for _, tt := range tests {
   139→		t.Run(tt.name, func(t *testing.T) {
