			wantErr:          true,
			wantUploadCalled: true,
		},
		{
			name: "compose up fails",
			setupMock: func(m *MockSSHClient) {
				m.SetCommandOutput("up -d", "", "docker daemon error", errors.New("compose up failed"))
			},
			up:               true,
			validate:         false,
			wantErr:          true,
			wantUploadCalled: true,
		},
	}

	for _, tt := range tests {
