// Integration-style unit test for validateComposeFile command format.
func TestStackResource_ValidateComposeFile_CommandFormat(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name         string
		remotePath   string
		wantDirPart  string
		wantFilePart string
	}{
		{
			name:         "standard path",
			remotePath:   "/opt/stacks/app/docker-compose.yaml",
			wantDirPart:  "cd '/opt/stacks/app'",
			wantFilePart: "-f 'docker-compose.yaml'",
		},
		{
			name:         "path with spaces",
			remotePath:   "/opt/my stacks/app/docker-compose.yaml",
			wantDirPart:  "cd '/opt/my stacks/app'",
			wantFilePart: "-f 'docker-compose.yaml'",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			mock := NewMockSSHClient()
			r := &StackResource{}

			_ = r.validateComposeFile(context.Background(), mock, tt.remotePath)

			// Check the command that was executed
			commands := mock.GetCommands()
			if len(commands) != 1 {
				t.Fatalf("Expected 1 command, got %d", len(commands))
			}

			cmd := commands[0]
			if !containsString(cmd, tt.wantDirPart) {
				t.Errorf("Command %q missing expected dir part %q", cmd, tt.wantDirPart)
			}
			if !containsString(cmd, tt.wantFilePart) {
				t.Errorf("Command %q missing expected file part %q", cmd, tt.wantFilePart)
			}
			if !containsString(cmd, "config --quiet") {
				t.Errorf("Command %q missing 'config --quiet'", cmd)
			}
		})
	}
}

// Test for ShellQuote usage in compose commands.
func TestStackResource_ComposeCommands_ShellEscaping(t *testing.T) {
	t.Parallel()

	// Test path with special characters that need escaping
	remotePath := "/opt/stack's/docker-compose.yaml"
	mock := NewMockSSHClient()
	r := &StackResource{}

	_ = r.composeUp(context.Background(), mock, remotePath)

	commands := mock.GetCommands()
	if len(commands) != 1 {
		t.Fatalf("Expected 1 command, got %d", len(commands))
	}

	// The command should properly escape the single quote
	cmd := commands[0]
	if containsString(cmd, "stack's") {
		t.Errorf("Command %q contains unescaped single quote", cmd)
	}
}

