func TestStackResource_CreateSSHClient_WithMock(t *testing.T) {
	t.Parallel()

	mock := NewMockSSHClient()
	factory := NewMockSSHClientFactory(mock)

	r := &StackResource{
		sshClientFactory: factory,
	}

	data := &StackResourceModel{
		Host:    types.StringValue("192.168.1.100"),
		SSHUser: types.StringValue("root"),
		SSHPort: types.Int64Value(22),
	}

	client, err := r.createSSHClient(data)
	if err != nil {
		t.Fatalf("createSSHClient() error = %v", err)
	}

	if client == nil {
		t.Error("createSSHClient() returned nil client")
	}

	// Verify it's our mock
	if _, ok := client.(*MockSSHClient); !ok {
		t.Error("createSSHClient() didn't return mock client")
	}
}

