// buildDefaultStateValues returns a map of default tftypes values for a stack resource.
// Pass overrides as a map to customize specific fields.
func buildDefaultStateValues(overrides map[string]tftypes.Value) map[string]tftypes.Value {
	defaults := map[string]tftypes.Value{
		"id":                       tftypes.NewValue(tftypes.String, tftypes.UnknownValue),
